const int redPin = 5;
const int yellowPin = 6;
const int greenPin = 7;

unsigned long previousMillis = 0;
const long redDuration = 5000;       // 5 секунд
const long redYellowDuration = 2000; // 2 секунд
const long greenDuration = 5000;     // 5 секунд
const long blinkDuration = 1000;     // 1 секунда для вспышки
const long yellowDuration = 2000;    // 2 секунды

int currentState = 0; // 0: Красный, 1: Красный+Желтый, 2: Зеленый, 3: Вспышка Желтого, 4: Желтый

void setup() {
  pinMode(redPin, OUTPUT);
  pinMode(yellowPin, OUTPUT);
  pinMode(greenPin, OUTPUT);
  digitalWrite(redPin, HIGH);
  digitalWrite(yellowPin, LOW);
  digitalWrite(greenPin, LOW);
}

void loop() {
  switch(currentState) {
    case 0: // Красный
      if (millis() - previousMillis >= redDuration) {
        currentState = 1;
        previousMillis = millis();
        digitalWrite(redPin, HIGH);
        digitalWrite(yellowPin, HIGH);
        digitalWrite(greenPin, LOW);
      }
      break;
    case 1: // Красный+Желтый
      if (millis() - previousMillis >= redYellowDuration) {
        currentState = 2;
        previousMillis = millis();
        digitalWrite(redPin, LOW);
        digitalWrite(yellowPin, LOW);
        digitalWrite(greenPin, HIGH);
      }
      break;
    case 2: // Зеленый
      if (millis() - previousMillis >= greenDuration) {
        currentState = 3;
        previousMillis = millis();
        digitalWrite(greenPin, LOW);
        digitalWrite(yellowPin, HIGH);
      }
      break;
    case 3: // Вспышка Желтого
      if (millis() - previousMillis >= blinkDuration) {
        currentState = 4;
        previousMillis = millis();
        digitalWrite(yellowPin, HIGH);
      } else {
        static unsigned long blinkStart = 0;
        if (millis() - blinkStart >= 500) {
          digitalWrite(yellowPin, !digitalRead(yellowPin));
          blinkStart = millis();
        }
      }
      break;
    case 4: // Желтый
      if (millis() - previousMillis >= yellowDuration) {
        currentState = 0;
        previousMillis = millis();
        digitalWrite(yellowPin, LOW);
        digitalWrite(redPin, HIGH);
        digitalWrite(greenPin, LOW);
      }
      break;
  }
}
